query:
CREATE TABLE IF NOT EXISTS keycloak_events (
  id SERIAL PRIMARY KEY,
  event_type VARCHAR(64) NOT NULL,
  user_id VARCHAR(128),
  realm_id VARCHAR(128),
  client_id VARCHAR(128),
  ip_address VARCHAR(64),
  session_id VARCHAR(128),
  error VARCHAR(256),
  details JSONB,
  received_at BIGINT NOT NULL DEFAULT EXTRACT(EPOCH FROM NOW()) * 1000
);

CREATE INDEX IF NOT EXISTS keycloak_events_type_idx ON keycloak_events (event_type);
CREATE INDEX IF NOT EXISTS keycloak_events_user_idx ON keycloak_events (user_id);
CREATE INDEX IF NOT EXISTS keycloak_events_received_idx ON keycloak_events (received_at);

